import {crops} from './life-state.js';
export function createGardenUI({context,action,close,toast}){
 const el=document.createElement('dialog');el.id='garden-picker';el.setAttribute('aria-label','花园');document.body.append(el);
 const ids=Object.keys(crops);let plot=0,cursor=0,world=null,working=false,serial=0,timer;
 const c=context,plant=()=>c().state.worlds[world]?.life?.plots?.[plot];
 function hide(){serial++;clearTimeout(timer);el.close();c().visual?.gardenSelect(-1)}
 function choose(index){cursor=Math.max(0,Math.min(ids.length-1,index));const wheel=el.querySelector('.garden-wheel');if(!wheel)return;wheel.setAttribute('aria-activedescendant','seed-'+ids[cursor]);wheel.querySelectorAll('[role=option]').forEach((o,i)=>o.setAttribute('aria-selected',i===cursor));}
 function render(){if(world!==c().world)return hide();const p=plant();el.innerHTML='<header><button data-prev aria-label="上一处花坛">‹</button><h2>'+ (p?crops[p.crop].name:'种花')+'</h2><button data-next aria-label="下一处花坛">›</button><button data-close aria-label="收起花园">×</button></header>'+(p?'<footer><button data-water '+(p.watered?'hidden':'')+'>浇水</button><button data-harvest>'+ (crops[p.crop].flower?'摘花':'采摘')+'</button></footer>':'<div class="sleep-wheel-shell"><div class="sleep-wheel-band"></div><div class="sleep-wheel garden-wheel" tabindex="0" role="listbox" aria-label="花和蔬果">'+ids.map((id,i)=>'<div role="option" id="seed-'+id+'" aria-selected="'+(i===cursor)+'"><i style="background:#'+crops[id].color.toString(16).padStart(6,'0')+'"></i>'+crops[id].name+'</div>').join('')+'</div></div><footer><button data-plant>种下</button></footer>');if(!el.open)el.show();c().visual?.gardenSelect(plot);
 el.querySelector('[data-close]').onclick=hide;el.querySelector('[data-prev]').onclick=()=>open((plot+5)%6);el.querySelector('[data-next]').onclick=()=>open((plot+1)%6);
 const wheel=el.querySelector('.garden-wheel');if(wheel){wheel.scrollTop=cursor*48;choose(cursor);wheel.onscroll=()=>{clearTimeout(timer);timer=setTimeout(()=>choose(Math.round(wheel.scrollTop/48)),100)};wheel.onclick=e=>{const option=e.target.closest('[role=option]');if(!option)return;choose(ids.indexOf(option.id.slice(5)));wheel.scrollTo({top:cursor*48,behavior:'smooth'})};wheel.onkeydown=e=>{if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();choose(e.key==='Home'?0:e.key==='End'?ids.length-1:cursor+(e.key==='ArrowDown'?1:-1));wheel.scrollTop=cursor*48};el.querySelector('[data-plant]').onclick=()=>{choose(Math.round(wheel.scrollTop/48));perform('plant',ids[cursor])}}else{el.querySelector('[data-water]').onclick=()=>perform('water',p.crop);el.querySelector('[data-harvest]').onclick=()=>perform('harvest',p.crop)}growth();}
 function growth(){if(!el.open||working)return;const p=plant();if(!p)return;const ready=p.readyAt<=Date.now();const harvest=el.querySelector('[data-harvest]');if(harvest)harvest.hidden=!ready;}
 async function perform(type,crop){if(working)return;working=true;const token=++serial,target=world,index=plot;el.close();try{const animated=await c().visual?.gardenAnimate(type,index,crop);if(animated===false||serial!==token||c().world!==target)return;await action({type,plot:index,crop});}finally{working=false;if(serial===token&&c().world===target)render()}}
 function open(index){if(working)return;close();world=c().world;plot=Number.isInteger(index)?index:Math.max(0,(c().state.worlds[world].life?.plots||[]).findIndex(p=>!p));c().visual?.inspectGarden();render()}
 el.addEventListener('cancel',hide);setInterval(growth,1000);return {open,hide};
}
